import{_ as s,B as o,o as r,c as l,a8 as d,a as t,E as i,f as a}from"./chunks/framework.CNIpabDg.js";const x=JSON.parse('{"title":"Command line shell (executable)","description":"The command-line shell provides bounded parsing, streaming command composition, built-ins, and native or WebAssembly executable dispatch.","frontmatter":{"layout":"doc","docType":"explanation","description":"The command-line shell provides bounded parsing, streaming command composition, built-ins, and native or WebAssembly executable dispatch."},"headers":[],"relativePath":"explanation/architecture/executables/command_line_shell.md","filePath":"explanation/architecture/executables/command_line_shell.md","lastUpdated":1793145952000}'),c={name:"explanation/architecture/executables/command_line_shell.md"};function u(p,e,h,m,b,f){const n=o("CodeReference");return r(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[8]||(e[8]=d(`<h1 id="command-line-shell-executable" tabindex="-1">Command line shell (executable) <a class="header-anchor" href="#command-line-shell-executable" aria-label="Permalink to &quot;Command line shell (executable)&quot;">​</a></h1><p>The command-line shell provides a small, bounded shell language for interactive terminal sessions and explicit <code>shell -c</code> command source or VFS scripts via <code>shell -s</code>. It dispatches built-ins or native/WebAssembly executables through Xila&#39;s task and virtual filesystem APIs without depending on a hosted POSIX shell.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><ul><li>Lexes and parses quoting, environment expansion, pipelines, conditionals, redirections, sequential lists, and background execution.</li><li>Dispatches built-in commands or resolves executable names through the task&#39;s <code>Paths</code> search locations.</li><li>Maintains foreground shell state such as the current directory and environment.</li><li>Runs pipeline stages and background lists in child tasks with inherited environments and isolated shell state.</li></ul><h2 id="startup-and-lifecycle" tabindex="-1">Startup and lifecycle <a class="header-anchor" href="#startup-and-lifecycle" aria-label="Permalink to &quot;Startup and lifecycle&quot;">​</a></h2><ol><li>Initializes <code>Shell</code> state with the current task and root directory.</li><li>Resolves <code>User</code> from the task environment; if absent, runs the interactive authentication flow.</li><li>Loads <code>Paths</code> and <code>Host</code> environment variables.</li><li>Runs the interactive line loop when no arguments are supplied.</li><li>Executes already-separated arguments literally, parses shell source with <code>-c</code>, or reads and executes lines from a VFS file with <code>-s</code>.</li><li>Reaps completed background tasks as new jobs start and waits for outstanding jobs when the shell exits.</li></ol><h2 id="parsing-and-execution-model" tabindex="-1">Parsing and execution model <a class="header-anchor" href="#parsing-and-execution-model" aria-label="Permalink to &quot;Parsing and execution model&quot;">​</a></h2><p>The lexer borrows slices from one bounded source line. The parser validates a token vector rather than allocating a syntax tree. Expansion happens when each command is prepared for execution.</p><p><code>|</code> binds more tightly than <code>&amp;&amp;</code> and <code>||</code>; the conditional operators have equal precedence and evaluate left to right. <code>;</code> separates sequential lists, while <code>&amp;</code> launches the preceding conditional list in the background. Input, output, append, and standard-error redirections are applied to one command from left to right.</p><p>Pipelines run stages concurrently through bounded asynchronous pipes, so command output is streamed rather than collected in full. A pipeline returns the last stage&#39;s status after all stages finish. Foreground built-ins can mutate the parent shell&#39;s directory and environment; pipeline/background built-ins cannot.</p><h2 id="runtime-integration-points" tabindex="-1">Runtime integration points <a class="header-anchor" href="#runtime-integration-points" aria-label="Permalink to &quot;Runtime integration points&quot;">​</a></h2><ul><li><code>task</code> for child tasks, environments, scheduling, and inherited execution context.</li><li><code>authentication</code> for the login fallback flow.</li><li><code>virtual_file_system</code> for command discovery, redirections, file utilities, and current-directory resolution.</li><li><code>xila::executable::execute</code> for non-built-in command execution.</li><li><code>file_system::Pipe</code>-style bounded streams for pipeline backpressure.</li></ul><h2 id="failure-and-status-semantics" tabindex="-1">Failure and status semantics <a class="header-anchor" href="#failure-and-status-semantics" aria-label="Permalink to &quot;Failure and status semantics&quot;">​</a></h2><ul><li>Built-in failures return status 1 unless a command defines another status.</li><li>Unknown commands return 127.</li><li>Malformed source passed to <code>shell -c</code>, or invalid script input, returns 2; scripts report the offending path and line.</li><li>External executable statuses are preserved within 0–255.</li><li><code>$?</code> expands to the previous foreground status; successfully starting a background list sets it to zero.</li><li>Command errors are written to standard error without terminating the interactive shell unless the shell itself exits.</li></ul><h2 id="bounded-resources" tabindex="-1">Bounded resources <a class="header-anchor" href="#bounded-resources" aria-label="Permalink to &quot;Bounded resources&quot;">​</a></h2><p>Shell-owned syntax and streaming resources have explicit limits: a 4096-byte source line, 256 tokens, 32 commands, 8 pipeline stages, 8192 bytes of expanded arguments/redirection paths per command, 512 buffered bytes per pipe, and 8 active background lists. These limits do not include memory allocated by launched programs, runtimes, or task infrastructure.</p><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: a bounded command shell with built-ins, executable discovery, composition, streaming pipes, redirection, quoting, and environment expansion.</li><li><strong>Current implementation</strong>: intentionally not a complete POSIX shell. It supports line-oriented VFS scripts, but not multiline grammar, command substitution, globbing, subshells, descriptor duplication such as <code>2&gt;&amp;1</code>, here-documents, or shell assignment syntax.</li><li>Built-ins are registered in one discoverable table used by both dispatch and <code>help</code>; recent utilities include <code>grep</code>, <code>realpath</code>, <code>touch</code>, <code>sleep</code>, <code>chmod</code>, <code>tree</code>, <code>mv</code>, <code>cp</code>, and <code>find</code> alongside the existing filesystem/network commands.</li></ul><p><code>cp SOURCE DESTINATION</code> copies a regular file through the VFS using a fixed 512-byte buffer. It creates or truncates the target (or appends the source filename when the target is a directory); it does not recursively copy directories.</p><p>For exact syntax, statuses, limits, and built-in discovery, see the <a href="/reference/shell.html">shell reference</a>.</p><h2 id="user-facing-command-invocation" tabindex="-1">User-facing command invocation <a class="header-anchor" href="#user-facing-command-invocation" aria-label="Permalink to &quot;User-facing command invocation&quot;">​</a></h2><p>The shell treats each mode differently. With no arguments it reads an interactive prompt. With <code>-c</code> it parses exactly one <strong>shell source string</strong>, while <code>-s PATH</code> reads one VFS script line at a time. Otherwise it executes already-separated arguments <strong>literally</strong>, without reparsing metacharacters as shell syntax.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command_line_shell -c &quot;echo hello | grep hello&quot;</span></span>
<span class="line"><span>command_line_shell echo &quot;hello world&quot;</span></span>
<span class="line"><span>command_line_shell -s /data/startup.xsh</span></span></code></pre></div><p>The first form parses a pipeline; the second supplies literal argument words; the third reads a script file. Script lines support LF/CRLF and retain directory/environment state between lines inside the launched shell task. Script failures normally do not stop subsequent commands, but parsing/read errors stop with status 2. Four nested noninteractive shell invocations are allowed. The <code>-c</code> mode requires exactly two arguments (the flag and the command source). Invalid UTF-8 input and oversized interactive lines return status 2.</p><h2 id="script-execution-and-bounded-find" tabindex="-1">Script execution and bounded find <a class="header-anchor" href="#script-execution-and-bounded-find" aria-label="Permalink to &quot;Script execution and bounded find&quot;">​</a></h2><p>A <code>shell -s PATH</code> invocation resolves a path relative to the inherited current directory or uses an absolute VFS path, reading the file while standard input remains independently available to its commands. Each line is bounded to 4096 source bytes, with a 4097-byte buffer allowing for CR before LF. Invalid UTF-8, malformed input, read errors or excessive line length identify the script path and line and stop with status 2. A script returns the last executed command status; <code>exit</code> stops script execution. Nested <code>-c</code>/<code>-s</code> invocations are bounded to four levels.</p><p>The <code>find</code> built-in walks from its optional starting directory, applies exact <code>--name</code> and type filters, streams paths, and limits depth to 32 and paths to 1024 bytes. It reports VFS/output errors instead of silently skipping them. See <a href="/reference/shell.html">the shell reference</a> for flags.</p><h2 id="implementation-boundaries" tabindex="-1">Implementation boundaries <a class="header-anchor" href="#implementation-boundaries" aria-label="Permalink to &quot;Implementation boundaries&quot;">​</a></h2><ul><li><code>tokenizer.rs</code> implements borrowed tokens and differentiates single quotes, double quotes, escapes, variable expansion and comments.</li><li><code>parser.rs</code> validates all tokens before execution, with <strong>4096 input bytes</strong>, <strong>256 tokens</strong>, <strong>32 commands</strong> and <strong>8 pipeline stages</strong> as limits.</li><li><code>execution.rs</code> handles conditions, streams, redirection and background tasks. Its <strong>8192-byte</strong> per-command expansion/output buffer bound and <strong>512-byte</strong> pipes provide backpressure.</li><li><code>resolver.rs</code> scans configured <code>Paths</code> directories in order; the <strong>first matching filename</strong> wins. It is not equivalent to a host OS PATH lookup.</li><li><code>commands/</code> contains the built-in dispatch table, including filesystem/network commands. Parent-shell state changes apply only to foreground built-ins; a pipeline or background command runs in its own child Shell.</li></ul><p>For example, a background command gets duplicated output/error streams but its stdin is redirected to <code>/devices/standard_io/null</code>; the parent prompt can continue without blocking on that job. Background handles are reaped and the shell joins remaining jobs before exiting.</p><h2 id="status-and-failure-details" tabindex="-1">Status and failure details <a class="header-anchor" href="#status-and-failure-details" aria-label="Permalink to &quot;Status and failure details&quot;">​</a></h2><p><code>$?</code> reflects the previous foreground status. Shell parsing failures return status 2, unknown commands 127, and most built-in errors 1. In a pipeline, the last stage&#39;s status wins after joining all stages; there is <strong>no pipefail mode</strong>. The shell does not offer globbing, command substitution, POSIX here-documents, shell-variable assignment statements or POSIX-style multiline scripts.</p><h3 id="source-and-api-references" tabindex="-1">Source and API references <a class="header-anchor" href="#source-and-api-references" aria-label="Permalink to &quot;Source and API references&quot;">​</a></h3>`,33)),t("ul",null,[t("li",null,[i(n,{repo:"applications",path:"executables/shell/command_line/src/lib.rs"}),e[0]||(e[0]=a(" — entrypoint and invocation modes.",-1))]),t("li",null,[i(n,{repo:"applications",path:"executables/shell/command_line/src/tokenizer.rs"}),e[1]||(e[1]=a(" — tokenization and quoting.",-1))]),t("li",null,[i(n,{repo:"applications",path:"executables/shell/command_line/src/parser.rs"}),e[2]||(e[2]=a(" — syntax validation and limits.",-1))]),t("li",null,[i(n,{repo:"applications",path:"executables/shell/command_line/src/execution.rs"}),e[3]||(e[3]=a(" — composition and child tasks.",-1))]),t("li",null,[i(n,{repo:"applications",path:"executables/shell/command_line/src/resolver.rs"}),e[4]||(e[4]=a(" — path lookup and precedence.",-1))]),e[5]||(e[5]=t("li",null,[t("a",{href:"/explanation/architecture/libraries/executable.html"},"Executable library"),a(" — native launch contract.")],-1))]),e[9]||(e[9]=t("h2",{id:"references",tabindex:"-1"},[a("References "),t("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),t("ul",null,[t("li",null,[i(n,{repo:"applications",path:"executables/shell/command_line"})]),e[6]||(e[6]=t("li",null,[t("a",{href:"/reference/shell.html"},"Shell reference")],-1)),e[7]||(e[7]=t("li",null,[t("a",{href:"/explanation/architecture/executables/terminal.html"},"Terminal")],-1))])])}const v=s(c,[["render",u]]);export{x as __pageData,v as default};
